#include <Adafruit_NeoPixel.h> // Подключаем библиотеку для работы с лентой

#define LED_PIN    11  // Пин Arduino, к которому подключен вход DIN ленты
#define LED_COUNT  30  // Укажите точное количество светодиодов на вашей ленте

// Создаем объект для управления лентой
Adafruit_NeoPixel strip = Adafruit_NeoPixel(LED_COUNT, LED_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  // Инициализируем генератор случайных чисел шумом со свободного пина A0
  randomSeed(analogRead(A0)); 

  strip.begin();            // Инициализация ленты
  strip.setBrightness(50);  // Яркость от 0 до 255 (ставим 50, чтобы не слепило)
  strip.show();             // Выключаем все пиксели при старте
}

void loop() {
  // Проходим по каждому светодиоду в ленте
  for (int i = 0; i < LED_COUNT; i++) {
    // Генерируем случайные значения для Красного, Зеленого и Синего (от 0 до 255)
    byte r = random(0, 256);
    byte g = random(0, 256);
    byte b = random(0, 256);

    // Задаем случайный цвет текущему светодиоду
    strip.setPixelColor(i, strip.Color(r, g, b));
  }

  strip.show(); // Отправляем команду на ленту, чтобы обновить цвета
  delay(500);   // Пауза 500 миллисекунд перед следующей сменой цветов
}
